/** 
 * Decreases the volume by one for the current audio stream. It will be ignored if the current volume is equal to  {@link #getMinVolume()}.
 */
public void decreaseVolume(){
  if (volume <= getMinVolume()) {
    return;
  }
  audioManager.adjustStreamVolume(streamType,AudioManager.ADJUST_LOWER,VOLUME_FLAGS);
  updateVolumeAndNotifyIfChanged();
}
